class CalendarPanel(QFrame):
    PAPER_TOP = 43  # 클립 PNG의 끊긴 철사 높이가 이 종이 윗테두리와 맞습니다
    """독립/리사이즈 가능한 구식 은행 달력. 날짜별 메모 2줄과 아날로그 동그라미를 지원합니다."""
    close_requested = pyqtSignal()
    PAPER = QColor('#FBFCFE')  # 웜톤을 뺀 아주 옅은 쿨 화이트

    def __init__(self, owner=None):
        super().__init__(None, Qt.WindowType.Tool | Qt.WindowType.FramelessWindowHint)
        self.owner = owner
        now = datetime.now(); self.year, self.month = now.year, now.month
        self._drag_offset = None
        self._note_edits = []
        self.setWindowTitle("나만의 숙제 달력")
        self.setMinimumSize(int(CALENDAR_W*0.85), int(CALENDAR_H*0.85))
        self.resize(round(CALENDAR_W * CALENDAR_DEFAULT_SCALE), round(CALENDAR_H * CALENDAR_DEFAULT_SCALE))
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.setStyleSheet("background: transparent; border: none;")
        self.prev_btn = QPushButton("‹", self); self.next_btn = QPushButton("›", self)
        for b in (self.prev_btn, self.next_btn):
            b.setFixedSize(78,78); b.setFont(app_font(62,QFont.Weight.Black,ui_scale=False))
            b.setStyleSheet("border:none; background:transparent; color:#252525;")
        self.prev_btn.clicked.connect(lambda: self.shift_month(-1)); self.next_btn.clicked.connect(lambda: self.shift_month(1))
        self.clip = PaperClipButton(self, paper_color="#FBFCFE")
        self.clip.clicked.connect(self.close_requested.emit)
        self.grip = QSizeGrip(self)
        self.grip.setStyleSheet("background: transparent; border: none;")
        # 6주 x 7일 x 2줄. 날짜가 없는 셀은 숨깁니다.
        for row in range(6):
            for col in range(7):
                for slot in range(2):
                    e = QLineEdit(self)
                    e.setFrame(False)
                    e.setMaxLength(24)
                    e.setFont(self._rounded_font(13, QFont.Weight.Bold))
                    e.setStyleSheet("QLineEdit { background: transparent; border: none; color:#252525; padding:0px 2px; }")
                    e.editingFinished.connect(lambda r=row,c=col,sl=slot,ed=e: self._save_note(r,c,sl,ed.text()))
                    e.hide()
                    self._note_edits.append((row,col,slot,e))
        self._position_controls()
        self._layout_note_editors()

    def _rounded_font(self, px, weight=QFont.Weight.Black):
        # 숫자는 Arial Rounded 계열을 우선하고, 한자는 Windows가 적절한 CJK glyph로 fallback합니다.
        f = QFont("Arial Rounded MT Bold")
        f.setPixelSize(max(8, int(px))); f.setWeight(weight)
        return f

    def _position_controls(self):
        # 화살표는 큰 월 숫자의 바로 좌우에 둡니다.
        left,right,mt,mh,*_ = self._calendar_geometry()
        cy = mt + (mh - self.prev_btn.height()) // 2
        cx = self.width() // 2
        self.prev_btn.move(cx - 150, cy)
        self.next_btn.move(cx + 72, cy)
        # PNG의 오른쪽 위 끊긴 철사 높이 == 종이 윗테두리.
        clip_y = self.PAPER_TOP - self.clip.contact_y() + 3
        self.clip.move(self.width()-128, clip_y)
        self.grip.setGeometry(self.width()-26, self.height()-26, 26, 26)
        self.clip.raise_(); self.prev_btn.raise_(); self.next_btn.raise_(); self.grip.raise_()

    def _calendar_geometry(self):
        import calendar
        margin = max(14, int(self.width()*0.025))
        left, right = margin, self.width()-margin
        # 상단은 '9 + 연도 + 요일'만 빽빽하게. 월 숫자용 rect는 글자보다 넉넉해 절대 잘리지 않습니다.
        month_top = self.PAPER_TOP + 4
        usable_h = self.height() - self.PAPER_TOP
        month_h = max(100, int(usable_h*0.125))
        header_top = month_top + month_h - max(6, int(self.height()*0.008))
        header_h = max(58, int(self.height()*0.072))
        grid_top = header_top + header_h
        grid_bottom = self.height() - max(28, int((self.height()-self.PAPER_TOP)*0.035))
        cell_w = (right-left)/7.0
        cell_h = (grid_bottom-grid_top)/6.0
        weeks = calendar.Calendar(firstweekday=6).monthdayscalendar(self.year,self.month)
        return left,right,month_top,month_h,header_top,header_h,grid_top,grid_bottom,cell_w,cell_h,weeks

    def _date_key_for_cell(self,row,col):
        *_, weeks = self._calendar_geometry()
        if row >= len(weeks): return None
        day = weeks[row][col]
        if not day: return None
        return f"{self.year:04d}-{self.month:02d}-{day:02d}"

    def _entry(self,key,create=False):
        if self.owner is None or not key: return None
        data = self.owner.calendar_data
        if create:
            return data.setdefault(key, {"notes":["", ""], "circled":False})
        return data.get(key)

    def _save_note(self,row,col,slot,text):
        key=self._date_key_for_cell(row,col)
        if not key: return
        entry=self._entry(key, True)
        notes=entry.setdefault("notes", ["",""])
        while len(notes)<2: notes.append("")
        notes[slot]=text.strip()
        if self.owner: self.owner.save_data()
        self.update()

    def _layout_note_editors(self):
        left,right,mt,mh,ht,hh,gt,gb,cw,ch,weeks=self._calendar_geometry()
        note_h=max(18, int(ch*0.18))
        for row,col,slot,e in self._note_edits:
            day = weeks[row][col] if row < len(weeks) else 0
            if not day:
                e.hide(); continue
            x=round(left+col*cw)+5
            y=round(gt+row*ch + ch*0.56 + slot*note_h)
            e.setGeometry(x,y,max(20,round(cw)-10),note_h)
            e.setFont(self._rounded_font(max(11,int(ch*0.105)), QFont.Weight.Bold))
            key=f"{self.year:04d}-{self.month:02d}-{day:02d}"
            entry=self._entry(key,False) or {}
            notes=entry.get("notes", ["",""])
            val=notes[slot] if slot < len(notes) else ""
            if not e.hasFocus() and e.text()!=val: e.setText(val)
            e.show(); e.raise_()
        self.clip.raise_(); self.prev_btn.raise_(); self.next_btn.raise_(); self.grip.raise_()

    def show_near(self, global_pos):
        self.move(global_pos); self.show(); self.raise_(); self.activateWindow(); self._layout_note_editors()

    def resizeEvent(self, event):
        if not getattr(self, "_aspect_locking", False):
            ratio = CALENDAR_W / CALENDAR_H
            old = event.oldSize(); new = event.size()
            if old.isValid():
                dw = abs(new.width()-old.width()); dh=abs(new.height()-old.height())
                self._aspect_locking=True
                try:
                    if dw>=dh:
                        th=max(self.minimumHeight(), round(new.width()/ratio))
                        if th!=new.height(): self.resize(new.width(),th)
                    else:
                        tw=max(self.minimumWidth(), round(new.height()*ratio))
                        if tw!=new.width(): self.resize(tw,new.height())
                finally: self._aspect_locking=False
        super().resizeEvent(event); self._position_controls(); self._layout_note_editors(); self.update()

    def mousePressEvent(self,event:QMouseEvent):
        # The white month header ends where the weekday boxes begin.
        # Child buttons still handle their own clicks (month arrows and clip).
        header_bottom = self._calendar_geometry()[4]
        if event.button()==Qt.MouseButton.LeftButton and event.position().y()<header_bottom:
            self._drag_offset=event.globalPosition().toPoint()-self.frameGeometry().topLeft(); event.accept(); return
        super().mousePressEvent(event)
    def mouseMoveEvent(self,event:QMouseEvent):
        if self._drag_offset is not None and event.buttons() & Qt.MouseButton.LeftButton:
            self.move(event.globalPosition().toPoint()-self._drag_offset); event.accept(); return
        super().mouseMoveEvent(event)
    def mouseReleaseEvent(self,event:QMouseEvent): self._drag_offset=None; super().mouseReleaseEvent(event)

    def mouseDoubleClickEvent(self,event:QMouseEvent):
        left,right,mt,mh,ht,hh,gt,gb,cw,ch,weeks=self._calendar_geometry()
        pos=event.position()
        if left <= pos.x() <= right and gt <= pos.y() <= gb:
            col=int((pos.x()-left)//cw); row=int((pos.y()-gt)//ch)
            if 0<=row<6 and 0<=col<7 and row<len(weeks):
                day=weeks[row][col]
                # 날짜 숫자가 있는 셀 상단을 더블클릭했을 때만 동그라미 토글.
                if day and pos.y() <= gt+row*ch+ch*0.54:
                    key=f"{self.year:04d}-{self.month:02d}-{day:02d}"
                    entry=self._entry(key,True); entry["circled"]=not bool(entry.get("circled",False))
                    if self.owner: self.owner.save_data()
                    self.update(); event.accept(); return
        super().mouseDoubleClickEvent(event)

    def closeEvent(self,event):
        if self.owner is not None and getattr(self.owner,'calendar_open',False):
            self.owner.calendar_open=False
            if hasattr(self.owner,'btn_calendar_clip'): self.owner.btn_calendar_clip.show()
        super().closeEvent(event)

    def shift_month(self,delta):
        m=self.month+delta; y=self.year
        if m<1: y,m=y-1,12
        elif m>12: y,m=y+1,1
        self.year,self.month=y,m
        self._layout_note_editors(); self.update()

    def _draw_wide_text(self,p,rect,flags,text,font,color,wide=1.10):
        p.save(); p.setPen(color); p.setFont(font)
        p.translate(rect.x(),rect.y()); p.scale(wide,1.0)
        rr=QRect(0,0,max(1,round(rect.width()/wide)),rect.height())
        p.drawText(rr,flags,text); p.restore()

    def _draw_squashed_text(self,p,rect,text,font,color,wide=1.18,tall=0.68):
        # 옛날 은행 달력의 납작하고 넓은 활자 느낌.
        p.save(); p.setPen(color); p.setFont(font)
        p.translate(rect.center())
        p.scale(wide, tall)
        rr=QRectF(-rect.width()/(2*wide), -rect.height()/(2*tall), rect.width()/wide, rect.height()/tall)
        p.drawText(rr, Qt.AlignmentFlag.AlignCenter, text)
        p.restore()

    def _draw_marker_circle(self,p,rect,key):
        # 완벽한 벡터원이 아니라 유성펜으로 2~3번 덧그린 듯한 비정형 타원.
        seed=sum(ord(c) for c in key)
        p.save(); p.setBrush(Qt.BrushStyle.NoBrush)
        for i,(dx,dy) in enumerate(((0,0),(1,-1),(-1,1))):
            alpha=(205,125,75)[i]
            pen=QPen(QColor(224,42,31,alpha), max(2.0,self.width()*0.0045-(i*0.45)), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap)
            p.setPen(pen)
            wobble=((seed+i*7)%5)-2
            rr=QRectF(rect.x()+dx-wobble*0.25, rect.y()+dy, rect.width()+wobble, rect.height()-wobble*0.35)
            p.drawEllipse(rr)
        p.restore()

    def paintEvent(self,event):
        super().paintEvent(event)
        p=QPainter(self); p.setRenderHint(QPainter.RenderHint.Antialiasing,True)
        paper_rect = QRectF(0, self.PAPER_TOP, self.width(), self.height()-self.PAPER_TOP)
        p.fillRect(paper_rect, self.PAPER)
        p.setPen(QPen(QColor('#111111'), 1.0)); p.setBrush(Qt.BrushStyle.NoBrush); p.drawRect(paper_rect.adjusted(0.5,0.5,-0.5,-0.5))
        left,right,mt,mh,ht,hh,gt,gb,cw,ch,weeks=self._calendar_geometry()

        # 월 숫자: 충분한 세로 rect 안에서 중앙 정렬해 9의 상/하단 clipping을 구조적으로 방지.
        month_font=self._rounded_font(max(84,int(self.height()*0.108)),QFont.Weight.Black)
        month_rect=QRect(left,mt,right-left,mh)
        self._draw_wide_text(p,month_rect,Qt.AlignmentFlag.AlignHCenter|Qt.AlignmentFlag.AlignVCenter,str(self.month),month_font,QColor('#E1261C'),1.08)

        headers=['日','月','火','水','木','金','土']
        hf=self._rounded_font(max(48,int((self.height()-self.PAPER_TOP)*0.061)),QFont.Weight.Black)
        for i,h in enumerate(headers):
            x=round(left+i*cw); w=round(cw)
            box=QRectF(x+1, ht+3, w-2, hh-6)
            bg=QColor('#D92722') if i==0 else QColor('#1769B0') if i==6 else QColor('#242424')
            p.setPen(QPen(QColor('#111111'),0.8)); p.setBrush(bg); p.drawRect(box)
            self._draw_wide_text(p,box.adjusted(3,2,-3,-2).toRect(),Qt.AlignmentFlag.AlignCenter,h,hf,QColor('#FFFFFF'),1.00)

        # 날짜판: 얇은 검정 격자 + 큰 둥근 숫자 + 일정용 밑줄 두 줄.
        for row in range(6):
            week=weeks[row] if row<len(weeks) else [0]*7
            for col,day in enumerate(week):
                x=round(left+col*cw); y=round(gt+row*ch); w=round(cw); h=round(ch)
                p.setPen(QPen(QColor('#242424'),0.75)); p.setBrush(Qt.BrushStyle.NoBrush); p.drawRect(x,y,w,h)
                if not day: continue
                key=f"{self.year:04d}-{self.month:02d}-{day:02d}"
                holiday = HOLIDAYS_2026.get(key) if self.year == 2026 else None
                color=QColor('#E1261C') if (col==0 or holiday) else QColor('#1769B0') if col==6 else QColor('#050505')
                df=self._rounded_font(max(43,int(ch*0.39)),QFont.Weight.Black)
                nr=QRect(x+2,y+1,w-4,max(44,int(ch*0.52)))
                self._draw_wide_text(p,nr,Qt.AlignmentFlag.AlignHCenter|Qt.AlignmentFlag.AlignVCenter,str(day),df,color,1.10)
                entry=self._entry(key,False) or {}
                if holiday:
                    # 공휴일명은 사용자 일정과 별개의 고정 인쇄 텍스트.
                    hf2=self._rounded_font(max(9,int(ch*0.085)),QFont.Weight.Bold)
                    p.setPen(QColor('#D92722')); p.setFont(hf2)
                    p.drawText(QRectF(x+3, y+ch*0.43, w-6, ch*0.12), Qt.AlignmentFlag.AlignHCenter|Qt.AlignmentFlag.AlignVCenter, holiday)
                if entry.get('circled'):
                    cr=QRectF(x+w*0.025, y+ch*0.015, w*0.95, ch*0.52)
                    self._draw_marker_circle(p,cr,key)
                # 메모 입력칸의 실제 underline. QLineEdit은 이 선 위에 투명하게 놓입니다.
                p.setPen(QPen(QColor('#777777'),0.8))
                base=y+ch*0.56
                note_h=max(18,int(ch*0.18))
                for slot in range(2):
                    ly=round(base+(slot+1)*note_h-2)
                    p.drawLine(x+6,ly,x+w-6,ly)

        # 우하단 resize 표시
        p.setPen(QPen(QColor('#777777'),1.2)); br=self.rect().bottomRight()
        for off in (8,13,18): p.drawLine(br.x()-off,br.y()-3,br.x()-3,br.y()-off)
        p.end()

class ModernTodoApp(QWidget):
    def __init__(self):
        super().__init__()
        self.old_pos = None
        self.scale_factor = 1.0
        self.is_custom_mode = False
        self.is_tag_edit_mode = False
        self.memo_text = ""
        self.setWindowTitle("나만의 숙제")
        self.setWindowIcon(create_legal_pad_icon())
        self.load_data()
        # UI 배율은 데이터와 함께 저장하고 다음 실행 때 복원합니다.
        self.scale_factor = float(self.settings.get("ui_scale", 1.0))
        if self.scale_factor not in (0.8, 1.0, 1.1, 1.25, 1.5):
            self.scale_factor = 1.0
        self.init_window()
        self.build_ui()
        self.apply_scale()
        self.update_minimum_width()
        QTimer.singleShot(0, self._startup_geometry_sync)

    def init_window(self):
        self.setWindowFlags(Qt.WindowType.FramelessWindowHint)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.resize(660, 880 + PAGE_MARKER_OVERHANG)
        self.update_minimum_width()

    # 커스텀 미리보기 제목 + 메타데이터가 잘리지 않는 실제 최소 폭을 계산합니다.
    def update_minimum_width(self):
        s = self.scale_factor
        if hasattr(self, "virtual_row"):
            title_w = self.virtual_row.lbl_title.fontMetrics().horizontalAdvance("커스텀 미리보기 숙제")
            check_w = int(16 * s)
            time_w = int(135 * s)
            delete_w = int(24 * s)
            spacing = int(8 * s)
            row_margins = 10
            outer_margins = MARGIN_RED_X + 16 + 16
            # 체크-제목-시간-삭제 영역 사이 spacing 3개 + 고정 scrollbar gutter.
            min_w = outer_margins + check_w + title_w + time_w + delete_w + SCROLLBAR_GUTTER + spacing * 3 + row_margins + 24
        else:
            min_w = MARGIN_RED_X + int(360 * s)
        self.setMinimumWidth(max(550, int(min_w)))
        self.setMinimumHeight(grid_pos(10))

    def resizeEvent(self, event: QResizeEvent):
        super().resizeEvent(event)
        self.sync_grid()
        # resize 도중에는 Qt가 이전 child geometry를 잠깐 유지할 수 있습니다.
        # 현재 event가 끝난 뒤 한 번만 레이아웃을 확정해 겹침 잔상을 줄입니다.
        QTimer.singleShot(0, self._settle_layout_geometry)
        if hasattr(self, "tag_bar_frame"):
            QTimer.singleShot(0, self.refresh_tag_geometry)
        if hasattr(self, "marker_bar"):
            QTimer.singleShot(0, self._position_page_markers)

    def _position_page_markers(self):
        if not hasattr(self, "marker_bar") or not hasattr(self, "main_bg"):
            return
        # 배율/닫기 컨트롤과 겹치지 않도록 오른쪽 끝에서 충분히 왼쪽으로 고정합니다.
        right = self.main_bg.geometry().right() - 150
        x = max(118, right - self.marker_bar.width())
        self.marker_bar.move(x, 0); self.marker_bar.raise_()
        if hasattr(self, "btn_calendar_clip"):
            close_x = self.btn_close.mapTo(self.shell, self.btn_close.rect().topLeft()).x()
            self.btn_calendar_clip.move(max(8, close_x - self.btn_calendar_clip.width() - 6), PAGE_MARKER_OVERHANG - self.btn_calendar_clip.contact_y() + 3)
            self.btn_calendar_clip.raise_()
        self._position_title_scale()

    def _position_title_scale(self):
        if not hasattr(self, "lbl_main_title"):
            return
        title = self.lbl_main_title
        origin = title.mapTo(self.main_bg, title.rect().topLeft())
        self.scale_combo.adjustSize()
        self.scale_combo.move(
            origin.x() + title.fontMetrics().horizontalAdvance(title.text()) + 6,
            origin.y() + title.height() - self.scale_combo.height() + 3,
        )
        self.scale_combo.raise_()

    def _update_marker_states(self):
        if not hasattr(self, "btn_main_marker"):
            return
        archive = self.stacked_widget.currentIndex() == 1 if hasattr(self, "stacked_widget") else False
        custom = bool(self.is_custom_mode) and not archive
        self.btn_main_marker.set_marker_state(active=(not archive and not custom))
        self.btn_archive_toggle.set_marker_state(active=archive)
        # 완료 페이지에서는 커스텀 슬롯을 당겨 채우지 않고 그 자리만 비웁니다.
        self.btn_custom.set_marker_state(active=custom, blank=archive)
        if hasattr(self, "scale_combo"):
            self.scale_combo.setVisible(custom)
            QTimer.singleShot(0, self._position_title_scale)

    def showEvent(self, event):
        super().showEvent(event)
        # 저장된 배율로 처음 열 때는 실제 행/스크롤바 geometry가 show 이전에는
        # 아직 확정되지 않습니다. 첫 paint 이후 실제 좌표를 기준으로 재동기화합니다.
        QTimer.singleShot(0, self._startup_geometry_sync)
        QTimer.singleShot(40, self._startup_geometry_sync)

    def _startup_geometry_sync(self):
        self._settle_layout_geometry()
        if hasattr(self, "virtual_row"):
            self.sync_preview_time_alignment()
        self._position_page_markers()
        if hasattr(self, "scroll") and self.stacked_widget.currentIndex() == 0 and not getattr(self, "_did_initial_bottom_scroll", False):
            self._did_initial_bottom_scroll = True
            QTimer.singleShot(0, lambda: self._restore_task_scroll(0, True))

    def _settle_layout_geometry(self):
        # 그리드 계산값은 바꾸지 않고 이미 계산된 Qt 레이아웃 geometry만 확정합니다.
        for layout in (getattr(self, "root_layout", None), getattr(self, "task_layout", None)):
            if layout is not None:
                layout.activate()
        if hasattr(self, "task_list_widget"):
            self.task_list_widget.updateGeometry()
            self.task_list_widget.update()
        if hasattr(self, "scroll"):
            self.scroll.viewport().update()
        if hasattr(self, "virtual_row"):
            self.sync_preview_time_alignment()

    def sync_grid(self):
        h = self.height()
        # 하단 여백도 같은 소수점 그리드에 맞춰 누적 반올림합니다.
        base = grid_pos(2)
        remainder = (h - base) % GRID_PITCH
        offset = round((remainder + 26) % GRID_PITCH)
        self.bottom_spacer.changeSize(10, offset, QSizePolicy.Policy.Minimum, QSizePolicy.Policy.Fixed)
        self.root_layout.invalidate()
        self.main_bg.update()

    def build_ui(self):
        self.shell = QFrame(self)
        shell_layout = QHBoxLayout(self.shell)
        shell_layout.setContentsMargins(0, PAGE_MARKER_OVERHANG, 0, 0)
        shell_layout.setSpacing(0)
        self.main_bg = LegalPadBackground(self.shell)
        shell_layout.addWidget(self.main_bg, stretch=1)
        # 달력은 레이아웃에 참여하지 않는 floating child입니다. 리갈패드 배율과 무관하게 항상 같은 크기입니다.
        self.calendar_open = False
        self.calendar_panel = CalendarPanel(self)
        self.calendar_panel.close_requested.connect(self.toggle_calendar_panel)
        self.calendar_panel.hide()
        outer = QVBoxLayout(self)
        outer.setContentsMargins(0, 0, 0, 0)
        outer.addWidget(self.shell)

        self.root_layout = QVBoxLayout(self.main_bg)
        self.root_layout.setContentsMargins(0, 0, 0, 0)
        self.root_layout.setSpacing(0)

        # 상단 헤더
        self.header_frame = QFrame()
        self.header_frame.setFixedHeight(grid_pos(2))
        h_layout = QVBoxLayout(self.header_frame)
        h_layout.setContentsMargins(0, 4, 18, 0)
        h_layout.setSpacing(0)

        ctrl_bar = QHBoxLayout()
        ctrl_bar.setSpacing(10)
        ctrl_bar.addStretch()

        # 페이지 마커/달력 클립은 일반 컨트롤이 아니라 리갈패드 윗변에 꽂힌 문구류처럼
        # shell 위에 떠 있는 overlay로 만듭니다. 실제 페이지 내용의 43.75px 좌표계에는 영향이 없습니다.
        self.marker_bar = QFrame(self.shell)
        self.marker_bar.setStyleSheet("background: transparent; border: none;")
        marker_lay = QHBoxLayout(self.marker_bar)
        marker_lay.setContentsMargins(0, 0, 0, 0)
        marker_lay.setSpacing(3)

        # 형광펜 팔레트를 그대로 쓰는 반투명 페이지 마커. 슬롯 크기/위치는 항상 고정합니다.
        self.btn_main_marker = PageMarkerButton("숙제", NEON_TEXT_COLORS[2])
        self.btn_main_marker.clicked.connect(self.show_main_page)
        marker_lay.addWidget(self.btn_main_marker)

        self.btn_archive_toggle = PageMarkerButton("완료한\n숙제", NEON_TEXT_COLORS[0])
        self.btn_archive_toggle.clicked.connect(self.toggle_archive_view)
        marker_lay.addWidget(self.btn_archive_toggle)

        self.btn_custom = PageMarkerButton("커스텀", NEON_TEXT_COLORS[4])
        self.btn_custom.clicked.connect(self.toggle_custom_mode)
        marker_lay.addWidget(self.btn_custom)

        self.marker_bar.setFixedSize(PAGE_MARKER_W * 3 + 6, PAGE_MARKER_H)
        self.marker_bar.raise_()

        # 클립은 페이지 마커와 별도 물건. 닫혔을 때 패드에, 열렸을 때 달력에 꽂힙니다.
        self.btn_calendar_clip = PaperClipButton(self.shell)
        self.btn_calendar_clip.clicked.connect(self.toggle_calendar_panel)
        self.btn_calendar_clip.raise_()
        self._update_marker_states()

        # 커스텀 화면에서 제목 오른쪽 아래에 배율을 표시합니다.
        self.scale_combo = QComboBox(self.main_bg)
        self.scale_combo.addItems(["80%","100%","110%","125%","150%"])
        self.scale_combo.setCurrentText(f"{int(self.scale_factor*100)}%")
        self.scale_combo.currentTextChanged.connect(self.on_scale_change)
        self.scale_combo.setFont(app_font(10, QFont.Weight.Bold)); self.scale_combo.setFixedWidth(70)
        self.scale_combo.setStyleSheet("QComboBox { border:1px solid #C4BC87; border-radius:3px; padding:1px 5px; background:rgba(255,255,255,80); color:#4F4A35; font-weight:bold;} QComboBox::drop-down{border:none;width:0px;} QComboBox::down-arrow{image:none;width:0;height:0;} QComboBox QAbstractItemView{background:#FFFDF0;color:#4F4A35;}")
        # Positioned beside the title after layout settles.
        self.scale_combo.setVisible(False)

        self.btn_close = QPushButton("×")
        self.btn_close.setFixedSize(int(24 * self.scale_factor), int(24 * self.scale_factor))
        self.btn_close.setFont(app_font(20, QFont.Weight.Normal))
        self.btn_close.setStyleSheet(f"QPushButton {{ border: none; background: transparent; font-weight: normal; color: {TEXT_COLOR}; }} QPushButton:hover {{ color: {MODULE_INACTIVE_HIGHLIGHT}; }}")
        self.btn_close.clicked.connect(self.close)
        ctrl_bar.addWidget(self.btn_close)
        h_layout.addLayout(ctrl_bar)

        title_bar = QHBoxLayout()
        title_bar.setContentsMargins(MARGIN_RED_X + 16, 0, 0, 2)
        self.lbl_main_title = QLabel("나만의 숙제")
        self.lbl_main_title.setFont(app_font(TITLE_FONT_PX, QFont.Weight.Black, ui_scale=False))
        self.lbl_main_title.setStyleSheet("color: #4F4A35; background: transparent; text-decoration: underline;")
        self.lbl_main_title.setAlignment(Qt.AlignmentFlag.AlignBottom | Qt.AlignmentFlag.AlignLeft)
        title_bar.addWidget(self.lbl_main_title)
        # 피치몬 트레이드마크를 작은 종이 스티커처럼 빨간 두 줄 왼쪽 여백에 비스듬히 부착.
        self.peachmon_sticker = QLabel(self.main_bg)
        src = QPixmap()
        src.loadFromData(base64.b64decode(PEACHMON_STICKER_B64))
        # v23: 사용자가 제작한 투명 다이컷 스티커 PNG를 그대로 사용합니다. 추가 마스크/사각 backing 없음.
        # v24: 사용자가 준 완성 스티커를 수정/마스크/회전 없이 그대로 축소만 합니다.
        sticker = src.scaled(96, 96, Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation)
        self.peachmon_sticker.setPixmap(sticker)
        self.peachmon_sticker.setFixedSize(sticker.size())
        self.peachmon_sticker.setStyleSheet("background: transparent; border: none;")
        self.peachmon_sticker.move(2, 0)
        self.peachmon_sticker.raise_()
        title_bar.addStretch()
        h_layout.addLayout(title_bar)
        self.root_layout.addWidget(self.header_frame)

        self.stacked_widget = QStackedWidget()
        self.root_layout.addWidget(self.stacked_widget)

        # 메인 페이지
        self.page_main = QWidget()
        page_main_layout = QVBoxLayout(self.page_main)
        page_main_layout.setContentsMargins(0, 0, 0, 0)
        page_main_layout.setSpacing(0)

        # 태그 프레임
        self.tag_wrapper = QFrame()
        tw_lay = QHBoxLayout(self.tag_wrapper)
        # 수정 버튼 중심을 숙제 삭제 × 중심과 같은 X축에 둡니다.
        tw_lay.setContentsMargins(MARGIN_RED_X + 16, 0, 32, 0)
        tw_lay.setSpacing(8)

        self.tag_bar_frame = QFrame()
        self.tag_flow_layout = TagFlowLayout(self.tag_bar_frame)
        self.tag_bar_frame.setLayout(self.tag_flow_layout)
        tw_lay.addWidget(self.tag_bar_frame, stretch=1)

        self.btn_tag_edit = SimplePencilButton()
        self.btn_tag_edit.clicked.connect(self.toggle_tag_edit_mode)
        # 태그가 여러 줄이어도 수정 버튼은 첫 번째 ruling 한 칸의 중앙에 고정합니다.
        self.tag_edit_slot = QFrame()
        self.tag_edit_slot.setFixedSize(20, grid_row_height(0))
        self.tag_edit_slot.setStyleSheet("background: transparent; border: none;")
        edit_slot_lay = QVBoxLayout(self.tag_edit_slot)
        edit_slot_lay.setContentsMargins(0, 0, 0, 0)
        edit_slot_lay.setSpacing(0)
        edit_slot_lay.addWidget(self.btn_tag_edit, alignment=Qt.AlignmentFlag.AlignHCenter | Qt.AlignmentFlag.AlignVCenter)
        tw_lay.addWidget(self.tag_edit_slot, alignment=Qt.AlignmentFlag.AlignTop)

        page_main_layout.addWidget(self.tag_wrapper)
        self.render_tags()

        # 커스텀 미리보기
        self.virtual_row_wrapper = QFrame()
        vr_lay = QVBoxLayout(self.virtual_row_wrapper)
        vr_lay.setContentsMargins(MARGIN_RED_X + 16, 0, 16, 0)
        vr_lay.setSpacing(0)
        self.virtual_row = VirtualCustomTaskRow(self.settings, self.scale_factor, self.refresh_task_list)
        self.virtual_row.setFixedHeight(grid_row_height(0))
        vr_lay.addWidget(self.virtual_row)
        self.virtual_row_wrapper.setVisible(False)
        page_main_layout.addWidget(self.virtual_row_wrapper)

        # 배율 컨트롤은 커스텀 화면의 제목 오른쪽 아래에 표시합니다.

        # 숙제 영역
        self.scroll_wrapper = QFrame()
        sw_lay = QVBoxLayout(self.scroll_wrapper)
        sw_lay.setContentsMargins(0, 0, 16, 0)
        sw_lay.setSpacing(0)

        self.scroll = GridScrollArea()
        self.scroll.setWidgetResizable(True)
        self.scroll.setFrameShape(QFrame.Shape.NoFrame)
        self.scroll.setStyleSheet("QScrollArea { background: transparent; border: none; } QScrollBar:vertical { border: none; background: transparent; width: 4px; } QScrollBar::handle:vertical { background: #BBB37E; border-radius: 2px; }")
        self.scroll.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOn)
        self.scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.scroll.verticalScrollBar().setSingleStep(round(GRID_PITCH))
        self.scroll.verticalScrollBar().rangeChanged.connect(self.sync_preview_time_alignment)

        self.task_list_widget = QWidget()
        self.task_list_widget.setStyleSheet("background: transparent;")
        self.task_layout = QVBoxLayout(self.task_list_widget)
        self.task_layout.setContentsMargins(0, 0, 0, 0)
        self.task_layout.setSpacing(0)
        self.task_layout.setAlignment(Qt.AlignmentFlag.AlignTop)

        self.scroll.setWidget(self.task_list_widget)
        sw_lay.addWidget(self.scroll)
        page_main_layout.addWidget(self.scroll_wrapper, stretch=1)

        # 자유 메모장
        self.memo_wrapper = QFrame()
        mw_lay = QVBoxLayout(self.memo_wrapper)
        mw_lay.setContentsMargins(MARGIN_RED_X + 16, 0, 16, 0)
        mw_lay.setSpacing(0)

        self.memo_frame = QFrame()

        memo_lay = QVBoxLayout(self.memo_frame)
        memo_lay.setContentsMargins(0, 0, 0, 0)
        memo_lay.setSpacing(0)

        self.memo_title_box = QFrame()
        self.memo_title_box.setFixedHeight(grid_row_height(0))
        self.memo_title_box.setStyleSheet("background: transparent; border: none;")
        mt_lay = QHBoxLayout(self.memo_title_box)
        mt_lay.setContentsMargins(0, 0, 0, 0)
        self.lbl_memo_title = QLabel("자유 메모")
        self.lbl_memo_title.setStyleSheet("font-weight: bold; color: #4F4A35; text-decoration: underline; background: transparent;")
        self.lbl_memo_title.setAlignment(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft)
        mt_lay.addWidget(self.lbl_memo_title)
        memo_lay.addWidget(self.memo_title_box)

        self.txt_memo = QTextEdit()
        self.txt_memo.setFrameShape(QFrame.Shape.NoFrame)
        self.txt_memo.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self.txt_memo.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.txt_memo.verticalScrollBar().setSingleStep(round(GRID_PITCH))
        self.txt_memo.document().setDocumentMargin(0)
        self.txt_memo.setStyleSheet("""
            QTextEdit {
                background: transparent; border: none; color: #4F4A35;
                padding: 0px; margin: 0px;
            }
            QScrollBar:vertical { border: none; background: transparent; width: 4px; }
            QScrollBar::handle:vertical { background: #BBB37E; border-radius: 2px; }
        """)
        self.txt_memo.setPlainText(self.memo_text)
        self.txt_memo.textChanged.connect(self.on_memo_change)
        memo_lay.addWidget(self.txt_memo)

        mw_lay.addWidget(self.memo_frame)
        page_main_layout.addWidget(self.memo_wrapper)

        # 커스텀 모드에서는 하이라이트 영역의 자식 위젯까지 클릭을 모듈 토글로 받습니다.
        # 태그 수정 버튼만 본래 편집 기능을 보존합니다.
        self._install_module_click_filter(self.tag_wrapper, "show_tags", exclusions=(self.btn_tag_edit,))
        self._install_module_click_filter(self.memo_wrapper, "show_memo")

        self.stacked_widget.addWidget(self.page_main)

        # 완료한 숙제 페이지
        self.page_archive = QWidget()
        page_archive_layout = QVBoxLayout(self.page_archive)
        page_archive_layout.setContentsMargins(0, 0, 0, 0)

        self.archive_scroll = GridScrollArea()
        self.archive_scroll.setWidgetResizable(True)
        self.archive_scroll.setFrameShape(QFrame.Shape.NoFrame)
        self.archive_scroll.setStyleSheet("QScrollArea { background: transparent; border: none; } QScrollBar:vertical { border: none; background: transparent; width: 4px; } QScrollBar::handle:vertical { background: #BBB37E; border-radius: 2px; }")
        self.archive_scroll.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self.archive_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.archive_scroll.verticalScrollBar().setSingleStep(round(GRID_PITCH))

        self.archive_container = QWidget()
        self.archive_container.setStyleSheet("background: transparent;")
        self.archive_layout = QVBoxLayout(self.archive_container)
        self.archive_layout.setContentsMargins(0, 0, 16, 0)
        self.archive_layout.setSpacing(0)
        self.archive_layout.setAlignment(Qt.AlignmentFlag.AlignTop)

        self.archive_scroll.setWidget(self.archive_container)
        page_archive_layout.addWidget(self.archive_scroll)
        self.stacked_widget.addWidget(self.page_archive)

        self.bottom_spacer = QSpacerItem(10, 0, QSizePolicy.Policy.Minimum, QSizePolicy.Policy.Fixed)
        self.root_layout.addSpacerItem(self.bottom_spacer)

        bottom_bar = QHBoxLayout()
        bottom_bar.setContentsMargins(0, 0, 3, 3)
        bottom_bar.addStretch()
        bottom_bar.addWidget(DottedSizeGrip(self))
        self.root_layout.addLayout(bottom_bar)

        self.update_memo_height()
        self.refresh_task_list()
        self.apply_visibility()

    def mousePressEvent(self, event):
        # Include the page-marker overhang above the paper in window coordinates.
        first_blue_y = self.main_bg.mapTo(self, self.main_bg.rect().topLeft()).y() + grid_pos(2)
        if event.button() == Qt.MouseButton.LeftButton and event.position().y() <= first_blue_y:
            self.old_pos = event.globalPosition().toPoint()
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        if self.old_pos:
            delta = event.globalPosition().toPoint() - self.old_pos
            self.move(self.pos() + delta)
            self.old_pos = event.globalPosition().toPoint()

    def mouseReleaseEvent(self, event): self.old_pos = None

    def toggle_tag_edit_mode(self):
        self.is_tag_edit_mode = not self.is_tag_edit_mode
        self.btn_tag_edit.is_edit_mode = self.is_tag_edit_mode
        self.btn_tag_edit.update()
        self.render_tags()

    def render_tags(self):
        while self.tag_flow_layout.count():
            i = self.tag_flow_layout.takeAt(0)
            if i.widget(): i.widget().deleteLater()

        s = self.scale_factor
        f_size = max(11, int(13 * s))

        for idx, tag_text in enumerate(self.tags):
            hl = NEON_TEXT_COLORS[idx % len(NEON_TEXT_COLORS)]
            hl_bg = blend_hex(hl)
            btn = QPushButton(tag_text)
            btn.setFont(app_font(f_size))
            btn.setCursor(Qt.CursorShape.PointingHandCursor)

            if self.is_tag_edit_mode:
                btn.setStyleSheet(f"""
                    QPushButton {{
                        background-color: {hl_bg}; border: none; border-radius: 3px;
                        color: #4F4A35; padding: 2px 6px;
                    }}
                    QPushButton:hover {{
                        background-color: #E6B2AD; color: #4F4A35;
                    }}
                """)
                btn.clicked.connect(lambda _, t=tag_text: self.quick_delete_tag(t))
            else:
                btn.setStyleSheet(f"""
                    QPushButton {{
                        background-color: {hl_bg}; border: none; border-radius: 3px;
                        color: #4F4A35; padding: 2px 6px;
                    }}
                """)
                btn.clicked.connect(lambda _, t=tag_text: self.insert_tag_to_top(t))

            self.tag_flow_layout.addWidget(btn)
            btn.setProperty("custom_module_key", "show_tags")
            btn.installEventFilter(self)

        self.new_tag_input = QLineEdit()
        self.new_tag_input.setPlaceholderText("+ 자주하는 숙제")
        self.new_tag_input.setFont(app_font(f_size))
        self.new_tag_input.setStyleSheet("border: 1px dashed #4F4A35; border-radius: 4px; padding: 2px 8px; background: transparent; color: #4F4A35;")
        self.new_tag_input.returnPressed.connect(self.add_tag_from_input)
        self.new_tag_input.textChanged.connect(self.adjust_new_tag_width)
        self.new_tag_input.setMinimumWidth(1)
        self.adjust_new_tag_width()
        self.tag_flow_layout.addWidget(self.new_tag_input)
        self.new_tag_input.setProperty("custom_module_key", "show_tags")
        self.new_tag_input.installEventFilter(self)
        # render 직후 기존 높이가 남아 첫 줄만 보이는 문제를 다음 event loop에서 재계산합니다.
        QTimer.singleShot(0, self.refresh_tag_geometry)

    def refresh_tag_geometry(self):
        if not hasattr(self, "tag_bar_frame"):
            return
        width = self.tag_bar_frame.width()
        if width <= 0:
            width = max(1, self.tag_wrapper.width() - (MARGIN_RED_X + 16) - 16 - 28)
        height = max(grid_row_height(0), self.tag_flow_layout.heightForWidth(width))
        self.tag_bar_frame.setFixedHeight(height)
        self.tag_wrapper.setFixedHeight(height)
        self.tag_flow_layout.invalidate()
        self.tag_bar_frame.updateGeometry()
        self.tag_wrapper.updateGeometry()
        if hasattr(self, "page_main"):
            self.page_main.updateGeometry()

    def adjust_new_tag_width(self):
        txt = self.new_tag_input.text() or self.new_tag_input.placeholderText()
        fm = self.new_tag_input.fontMetrics()
        # 입력 문자열 전체가 보이도록 내용과 함께 필드가 자랍니다.
        self.new_tag_input.setFixedWidth(max(1, fm.horizontalAdvance(txt) + fm.horizontalAdvance("가") + 24))
        QTimer.singleShot(0, self.refresh_tag_geometry)

    def add_tag_from_input(self):
        t = self.new_tag_input.text().strip().replace("#", "")
        if t and t not in self.tags:
            self.tags.append(t)
            self.save_data()
            self.render_tags()
            self.sync_grid()

    def insert_tag_to_top(self, tag_name):
        self.tasks.append({
            "id": datetime.now().strftime("%Y%m%d%H%M%S%f"),
            "text": f"{tag_name} ",
            "completed": False,
            "created_at": datetime.now().strftime("%Y-%m-%d %H:%M"),
            "completed_at": None,
            "kind": "frequent"
        })
        self.save_data()
        self.refresh_task_list(scroll_to_bottom=True)

    def quick_delete_tag(self, tag_name):
        self.tags = [t for t in self.tags if t != tag_name]
        self.save_data()
        self.render_tags()
        self.sync_grid()

    def _partition_tasks(self):
        now = datetime.now()
        active, archive = [], []
        for t in self.tasks:
            if t.get("completed") and t.get("completed_at"):
                ct = parse_dt(t.get("completed_at"))
                if ct and now >= next_flush_after(ct):
                    archive.append(t)
                    continue
            active.append(t)
        return active, archive

    def _active_sort_key(self, task):
        # 오래된 날짜가 위. 같은 날은 자주하는 숙제 → 일반 숙제, 그 안에서는 등록 순서.
        # 완료 여부는 정렬에 관여하지 않습니다. 체크한 자리의 시간 흐름을 보존합니다.
        day = task_logical_date(task)
        kind = task.get("kind", "frequent" if task.get("is_tag_header") else "normal")
        kind_rank = 0 if kind == "frequent" else 1
        created = parse_dt(task.get("created_at")) or datetime.min
        return (day, kind_rank, created)

    def refresh_task_list(self, scroll_to_bottom=False):
        old_value = self.scroll.verticalScrollBar().value() if hasattr(self, "scroll") else 0
        while self.task_layout.count():
            item = self.task_layout.takeAt(0)
            if item.widget(): item.widget().deleteLater()

        active_list, archive_list = self._partition_tasks()
        active_list = sorted(active_list, key=self._active_sort_key)
        previous_day = None
        for idx, t_data in enumerate(active_list):
            day = task_logical_date(t_data)
            date_text = day.strftime("%m.%d") if day != previous_day else ""
            previous_day = day
            row = NoteTaskRow(t_data, self.scale_factor, self.settings, date_text=date_text)
            row.setFixedHeight(grid_row_height(idx))
            row.changed.connect(self.on_task_row_changed)
            row.text_changed.connect(self.on_task_text_changed)
            row.delete_requested.connect(self.remove_task_row)
            self.task_layout.addWidget(row)

        self.add_inline_input_row(row_index=len(active_list))
        self.render_archive_page(sorted(archive_list, key=lambda t: (parse_dt(t.get("completed_at")) or datetime.min)))
        if hasattr(self, "virtual_row") and self.virtual_row.isVisible():
            QTimer.singleShot(0, self.sync_preview_time_alignment)
        QTimer.singleShot(0, lambda: self._restore_task_scroll(old_value, scroll_to_bottom))

    def _restore_task_scroll(self, old_value, scroll_to_bottom):
        if not hasattr(self, "scroll"):
            return
        bar = self.scroll.verticalScrollBar()
        bar.setValue(bar.maximum() if scroll_to_bottom else min(old_value, bar.maximum()))

    def on_task_row_changed(self):
        self.save_data()
        self.refresh_task_list()

    def on_task_text_changed(self):
        self.save_data()

    def add_inline_input_row(self, row_index=0):
        s = self.scale_factor
        f = QFrame()
        f.setFixedHeight(grid_row_height(row_index))
        f.setStyleSheet("background: transparent; border: none;")
        lay = QHBoxLayout(f)
        lay.setContentsMargins(0, 0, 10, 0)
        lay.setSpacing(int(8 * s))

        date_space = QLabel("")
        date_space.setFixedWidth(MARGIN_RED_X + 8)
        lay.addWidget(date_space)

        chk = QLabel()
        chk.setFixedSize(int(16 * s), int(16 * s))
        chk.setStyleSheet("border: 1px solid #4F4A35; border-radius: 0px; background: transparent;")
        lay.addWidget(chk)

        edit = QLineEdit()
        edit.setFrame(False)
        edit.setFont(app_font(max(12, int(15 * s))))
        edit.setPlaceholderText("새로운 숙제를 추가하세요")
        edit.setStyleSheet("color: #4F4A35; background: transparent; border: none;")
        edit.returnPressed.connect(lambda: self.commit_inline_task(edit))
        lay.addWidget(edit, stretch=1)
        self.task_layout.addWidget(f)

    def commit_inline_task(self, edit_widget):
        txt = edit_widget.text().strip()
        if not txt: return
        self.tasks.append({
            "id": datetime.now().strftime("%Y%m%d%H%M%S%f"),
            "text": txt,
            "completed": False,
            "created_at": datetime.now().strftime("%Y-%m-%d %H:%M"),
            "completed_at": None,
            "kind": "normal"
        })
        self.save_data()
        self.refresh_task_list(scroll_to_bottom=True)

    def remove_task_row(self, row_widget):
        self.tasks = [t for t in self.tasks if t["id"] != row_widget.data["id"]]
        self.save_data()
        self.refresh_task_list()

    def render_archive_page(self, archive_items):
        while self.archive_layout.count():
            item = self.archive_layout.takeAt(0)
            if item.widget(): item.widget().deleteLater()

        s = self.scale_factor
        f_size = max(11, int(14 * s))
        previous_archive_date = None
        for idx, t in enumerate(archive_items):
            row = QFrame()
            row.setFixedHeight(grid_row_height(idx))
            row.setStyleSheet("background: transparent;")
            lay = QHBoxLayout(row)
            lay.setContentsMargins(0, 0, 10, 0)
            lay.setSpacing(0)

            dt_str = ""
            if t.get("completed_at"):
                try: dt_str = datetime.strptime(t["completed_at"], "%Y-%m-%d %H:%M").strftime("%m.%d")
                except Exception: pass
            shown_date = dt_str if dt_str and dt_str != previous_archive_date else ""
            if dt_str:
                previous_archive_date = dt_str

            lbl_date = QLabel(shown_date)
            lbl_date.setFixedWidth(MARGIN_RED_X - 6)
            lbl_date.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
            lbl_date.setFont(app_font(max(1, int(11 * s)), QFont.Weight.Bold))
            lbl_date.setStyleSheet("color: #E8706D; background: transparent; padding-right: 8px;")
            lay.addWidget(lbl_date)

            lbl_content = QLineEdit(t.get("text", ""))
            lbl_content.setFrame(False)
            lbl_content.setFont(app_font(f_size))
            lbl_content.setReadOnly(True)
            lbl_content.setStyleSheet("color: #918B78; text-decoration: line-through; background: transparent; padding-left: 20px;")
            lay.addWidget(lbl_content, stretch=1)

            lbl_time = QLabel(t["completed_at"].split(" ")[-1] if t.get("completed_at") else "")
            lbl_time.setFont(app_font(max(1, int(10 * s))))
            lbl_time.setStyleSheet("color: #918B78;")
            lay.addWidget(lbl_time)
            self.archive_layout.addWidget(row)

    def show_main_page(self):
        self.stacked_widget.setCurrentIndex(0)
        self.lbl_main_title.setText("나만의 숙제")
        self.is_custom_mode = False
        self._update_marker_states()
        self._position_page_markers()
        self.virtual_row_wrapper.setVisible(False)
        if hasattr(self, "custom_scale_bar"): self.custom_scale_bar.setVisible(False)
        self.apply_visibility()
        QTimer.singleShot(0, lambda: self._restore_task_scroll(0, True))

    def toggle_archive_view(self):
        self.is_custom_mode = False
        self.stacked_widget.setCurrentIndex(1)
        self.lbl_main_title.setText("완료한 숙제")
        self._update_marker_states()
        self._position_page_markers()

    def toggle_calendar_panel(self):
        if not getattr(self, "calendar_open", False):
            self.calendar_open = True
            self.btn_calendar_clip.hide()
            # 리갈패드 창 크기는 전혀 바꾸지 않습니다. 달력은 고정 크기의 도구창으로 바깥까지 이동 가능.
            g = self.mapToGlobal(self.rect().topRight())
            self.calendar_panel.show_near(g + QPointF(12, PAGE_MARKER_OVERHANG).toPoint())
        else:
            self.calendar_open = False
            self.calendar_panel.hide()
            self.btn_calendar_clip.show(); self.btn_calendar_clip.raise_()
        QTimer.singleShot(0, self._position_page_markers)

    def toggle_custom_mode(self):
        if self.stacked_widget.currentIndex() != 0:
            self.stacked_widget.setCurrentIndex(0)
            self.lbl_main_title.setText("나만의 숙제")
        self.is_custom_mode = not self.is_custom_mode
        if self.is_custom_mode:
            self.virtual_row_wrapper.setVisible(True)
            self.tag_wrapper.setVisible(True)
            self.memo_wrapper.setVisible(True)
            self.update_custom_mode_styles()
        else:
            self.virtual_row_wrapper.setVisible(False)
            self.apply_visibility()
            self.save_data()
            self.refresh_task_list()
        self._update_marker_states()
        self._position_page_markers()

    def _install_module_click_filter(self, root, key, exclusions=()):
        root.setProperty("custom_module_key", key)
        root.installEventFilter(self)
        for child in root.findChildren(QWidget):
            if child in exclusions:
                continue
            child.setProperty("custom_module_key", key)
            child.installEventFilter(self)

    def eventFilter(self, obj, event):
        if self.is_custom_mode and event.type() == QEvent.Type.MouseButtonPress:
            key = obj.property("custom_module_key") if isinstance(obj, QWidget) else None
            if key and event.button() == Qt.MouseButton.LeftButton:
                self.settings[key] = not self.settings.get(key, True)
                self.update_custom_mode_styles()
                return True
        return super().eventFilter(obj, event)

    def on_module_click(self, key, widget):
        if not self.is_custom_mode:
            return
        self.settings[key] = not self.settings.get(key, True)
        self.update_custom_mode_styles()

    def update_custom_mode_styles(self):
        tag_active = self.settings.get("show_tags", True)
        # 이 두 색은 커스텀 모드 영역 하이라이트 전용입니다. 실제 alpha로 칠해
        # 뒤의 legal-pad ruling이 비치도록 합니다.
        tag_rgb = (121, 167, 194) if tag_active else (200, 111, 106)
        self.tag_wrapper.setStyleSheet(
            f"background-color: rgba({tag_rgb[0]}, {tag_rgb[1]}, {tag_rgb[2]}, 118); border-radius: 4px;"
        )
        self.tag_bar_frame.setStyleSheet("background: transparent; border: none;")
        self.btn_tag_edit.setStyleSheet("background: transparent; border: none;")

        memo_active = self.settings.get("show_memo", True)
        memo_rgb = (121, 167, 194) if memo_active else (200, 111, 106)
        self.memo_wrapper.setStyleSheet(
            f"background-color: rgba({memo_rgb[0]}, {memo_rgb[1]}, {memo_rgb[2]}, 118); border-radius: 4px;"
        )
        self.memo_frame.setStyleSheet("background: transparent; border: none;")
        self.memo_title_box.setStyleSheet("background: transparent; border: none;")
        self.lbl_memo_title.setStyleSheet("font-weight: bold; color: #4F4A35; text-decoration: underline; background: transparent;")

    def apply_visibility(self):
        self.tag_wrapper.setStyleSheet("background: transparent; border: none;")
        self.tag_bar_frame.setStyleSheet("background: transparent; border: none;")
        self.memo_wrapper.setStyleSheet("background: transparent; border: none;")
        self.memo_frame.setStyleSheet("background: transparent; border: none;")
        self.memo_title_box.setStyleSheet("background: transparent; border: none;")
        self.lbl_memo_title.setStyleSheet("font-weight: bold; color: #4F4A35; background: transparent; text-decoration: underline;")
        self.tag_wrapper.setVisible(self.settings.get("show_tags", True))
        self.memo_wrapper.setVisible(self.settings.get("show_memo", True))
        self.sync_grid()

    def on_memo_change(self):
        self.memo_text = self.txt_memo.toPlainText()
        self.update_memo_height()
        self.save_data()

    def update_memo_height(self):
        lines_count = len(self.memo_text.split("\n"))
        edit_lines = max(1, min(4, lines_count))
        self.memo_frame.setFixedHeight(grid_pos(1 + edit_lines))
        self.txt_memo.setFixedHeight(grid_pos(edit_lines))
        self.apply_memo_line_spacing()
        self.sync_grid()

    def apply_memo_line_spacing(self):
        try:
            self.txt_memo.blockSignals(True)
            cursor = self.txt_memo.textCursor()
            cursor.select(QTextCursor.SelectionType.Document)
            fmt = QTextBlockFormat()
            fmt.setLineHeight(float(GRID_PITCH), QTextBlockFormat.LineHeightTypes.FixedHeight.value)
            cursor.mergeBlockFormat(fmt)
            self.txt_memo.blockSignals(False)
        except Exception:
            self.txt_memo.blockSignals(False)

    def sync_preview_time_alignment(self, *_):
        """미리보기 time_box를 실제 숙제 time_box의 화면 X좌표에 맞춥니다.

        고정 4px 추정치가 아니라 현재 렌더링된 실제 행의 geometry를 측정하므로
        배율과 스크롤바 상태가 바뀌어도 같은 X축을 사용합니다.
        """
        if not hasattr(self, "virtual_row"):
            return
        self.virtual_row.set_scrollbar_width(SCROLLBAR_GUTTER)
        actual_row = None
        for i in range(self.task_layout.count()):
            w = self.task_layout.itemAt(i).widget()
            if isinstance(w, NoteTaskRow):
                actual_row = w
                break
        if actual_row is None or not actual_row.isVisible() or not self.virtual_row.isVisible():
            return
        actual_x = actual_row.time_box.mapToGlobal(actual_row.time_box.rect().topRight()).x()
        preview_x = self.virtual_row.time_box.mapToGlobal(self.virtual_row.time_box.rect().topRight()).x()
        delta = preview_x - actual_x
        if delta:
            self.virtual_row.adjust_trailing_spacer(delta)

    def on_scale_change(self, text):
        self.scale_factor = int(text.replace("%", "")) / 100.0
        self.settings["ui_scale"] = self.scale_factor
        self.save_data()
        self.apply_scale()
        self.render_tags()
        self.virtual_row.set_scale(self.scale_factor)
        self.update_minimum_width()
        self.refresh_task_list()
        self.sync_preview_time_alignment()

    def apply_scale(self):
        s = self.scale_factor
        if hasattr(self, "marker_bar"):
            self.marker_bar.setFixedSize(PAGE_MARKER_W * 3 + 6, PAGE_MARKER_H)
        if hasattr(self, "btn_close"):
            close_px = max(24, int(24 * s))
            self.btn_close.setFixedSize(close_px, close_px)
            self.btn_close.setFont(app_font(20, QFont.Weight.Normal))
        f_main = max(12, int(15 * s))
        self.lbl_memo_title.setFont(app_font(max(18, int(22 * s)), QFont.Weight.Bold))
        self.txt_memo.setFont(app_font(f_main))
        self.apply_memo_line_spacing()

    def _migrate_data(self, d):
        """v12 JSON을 v13 스키마로 한 번 읽어 정규화합니다."""
        if not isinstance(d, dict):
            d = {}
        tasks = d.get("tasks", []) if isinstance(d.get("tasks", []), list) else []
        migrated = []
        for raw in tasks:
            if not isinstance(raw, dict):
                continue
            t = dict(raw)
            t.setdefault("id", datetime.now().strftime("%Y%m%d%H%M%S%f"))
            t.setdefault("text", "")
            t.setdefault("completed", False)
            t.setdefault("created_at", datetime.now().strftime("%Y-%m-%d %H:%M"))
            t.setdefault("completed_at", None)
            if "kind" not in t:
                t["kind"] = "frequent" if t.get("is_tag_header", False) else "normal"
            t.pop("is_tag_header", None)
            migrated.append(t)
        settings = {
            "show_tags": True, "show_memo": True,
            "show_created_date": True, "show_created_time": True,
            "show_completed_date": True, "show_completed_time": True,
            "ui_scale": 1.0
        }
        if isinstance(d.get("settings"), dict): settings.update(d["settings"])
        return {
            "schema_version": SCHEMA_VERSION,
            "tasks": migrated,
            "frequent_tasks": d.get("frequent_tasks", d.get("tags", [])),
            "memo": d.get("memo", d.get("memo_text", "")),
            "settings": settings,
            "calendar": d.get("calendar", {}) if isinstance(d.get("calendar", {}), dict) else {},
        }

    def load_data(self):
        base = self._migrate_data({})
        if os.path.exists(DATA_FILE):
            try:
                with open(DATA_FILE, "r", encoding="utf-8") as f:
                    base = self._migrate_data(json.load(f))
            except Exception:
                pass
        self.tasks = base["tasks"]
        self.tags = base["frequent_tasks"]
        self.memo_text = base["memo"]
        self.settings = base["settings"]
        self.calendar_data = base.get("calendar", {})

    def save_data(self):
        d = {
            "schema_version": SCHEMA_VERSION,
            "tasks": self.tasks,
            "frequent_tasks": self.tags,
            "memo": self.memo_text,
            "settings": self.settings,
            "calendar": self.calendar_data,
        }
        with open(DATA_FILE, "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

if __name__ == "__main__":
    app = QApplication(sys.argv)
    win = ModernTodoApp()
    win.show()
    sys.exit(app.exec())